"""Speaking, units 1-6. Two question types for every objective.

A RemNote card cannot grade a delivery, so an objective written as "in a timed rep, do X" is drilled as the thing a
card can hold: what the target is and what counts as meeting it, plus the arithmetic that measures it from a
recording — words per minute, filler rate, seconds to the point, segment lengths. The rep itself stays in the
practice log, not on a card. Targets come from the framework's own essential knowledge.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "spk-core-1", "speaking", "P1"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
VO, PA, PR, SR, IM, EX = ("speak.voice", "speak.pace", "speak.presence", "speak.structure",
                          "speak.impromptu", "speak.explain")


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


